 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(n){const parent=n.parentElement;return !parent||['SCRIPT','STYLE','TEXTAREA','OPTION'].includes(parent.tagName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const source=node.nodeValue,trim=source.trim();if(!trim)return;let localized=TITLE_ZH[trim]||map[trim];if(!localized)localized=trim.replace(/\bPipeline\b/g,'处理流程').replace(/\bVideo\b/g,'视频').replace(/\bSentence\b/g,'句子').replace(/(\d+) sentences/g,'$1 个句子');if(localized!==trim)node.nodeValue=source.replace(trim,localized)});
