function view(html,title){const content=title==='Dashboard'?adminWizardMarkup()+html:html;$('#view').innerHTML=content;setBreadcrumb(title);localizeAdminView($('#view'));hydrateIcons($('#view'));bindViewActions()}
function render(){const path=routePath();navSync(path);updateCounts();if(path==='/dashboard')return renderDashboard();if(path==='/trash')return renderTrash();if(path==='/videos')return renderVideos();if(path.startsWith('/videos/'))return renderVideoDetail(path.split('/')[2]);if(path==='/pipeline')return renderPipeline();if(path==='/subtitles')return renderSubtitlePicker();if(path.startsWith('/subtitles/'))return renderSubtitleEditor(path.split('/')[2]);if(path==='/creators')return renderCreators();if(path==='/collections')return renderCollections();if(path==='/analytics')return renderAnalytics();if(path==='/settings')return renderSettings();location.hash='#/dashboard'}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
