 async function bindAdminAuth(){const form=$('#adminAuthForm');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const phone=$('#adminAuthUser')?.value.trim(),pass=$('#adminAuthPass')?.value||'',error=$('#adminAuthError'),button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='验证中…';const result=await window.EastudyAuth?.signInPhone({phone,password:pass},'admin');if(result?.error){if(error)error.textContent=result.error.message||'管理员登录失败。';button.disabled=false;button.textContent='进入管理端';return}const context=await window.EastudyAuth.getContext('admin');if(!context.user||context.profile?.role!=='admin'){await window.EastudyAuth.signOut('admin');if(error)error.textContent='该账号没有管理员权限。';button.disabled=false;button.textContent='进入管理端';return}AdminAuth.context=context;if(error)error.textContent='';setAdminAuthenticated(true);$('#adminAuthGate')?.setAttribute('hidden','');await loadAdminCloud();render();toast('已进入 Eastudy 管理端');button.disabled=false;button.textContent='进入管理端'});$('#adminLogoutBtn')?.addEventListener('click',async()=>{await window.EastudyAuth?.signOut('admin');await Cloud?.clearMediaSession();AdminAuth.context=null;showAdminAuth();toast('已退出管理端')})}
 async function initAdminAuth(){const context=await window.EastudyAuth?.getContext('admin');if(context?.user&&context.profile?.role==='admin'){AdminAuth.context=context;setAdminAuthenticated(true);await loadAdminCloud();render();return}if(context?.user)await window.EastudyAuth.signOut('admin');showAdminAuth()}
